import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Docs-Source Consistency Audit — faultdeck · 2026-11-02 (G3 batch)","description":"","frontmatter":{},"headers":[],"relativePath":"审计-文档一致性.md","filePath":"审计-文档一致性.md"}`),a={name:`审计-文档一致性.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="docs-source-consistency-audit-—-faultdeck-·-2026-11-02-g3-batch" tabindex="-1">Docs-Source Consistency Audit — faultdeck · 2026-11-02 (G3 batch) <a class="header-anchor" href="#docs-source-consistency-audit-—-faultdeck-·-2026-11-02-g3-batch" aria-label="Permalink to “Docs-Source Consistency Audit — faultdeck · 2026-11-02 (G3 batch)”">​</a></h1><ul><li>Scope: <code>README.md</code> / <code>README.zh.md</code> / <code>docs/**</code> / <code>todo.md</code></li><li>Method: <code>~/workspaces/standards/文档与源码一致性审计规范.md</code> (three buckets + six steps); every claim evidenced at file:line; negative conclusions verified the search path first</li><li>Fix direction: source-wins — docs move toward the tree, never the reverse</li></ul><h2 id="key-state-of-the-repo" tabindex="-1">Key state of the repo <a class="header-anchor" href="#key-state-of-the-repo" aria-label="Permalink to “Key state of the repo”">​</a></h2><p><strong>Updated 2026-11-03 (supersedes the original 2026-11-02 &quot;no implementation&quot; snapshot below the line):</strong> the repository now carries a working implementation — a six-crate Cargo workspace: <code>crates/core</code> (shared <code>FaultSpec</code>/<code>Target</code>/<code>Injection</code> model + <code>validate_injection</code> + management-network overlap check), <code>crates/netem</code> (<code>tc qdisc</code>/<code>filter</code> adapter with preflight, rollback, <code>dry_run</code> executor), <code>crates/agent</code> (resident daemon, token auth, Mode A/B transport, iptables firewall), <code>crates/cli</code> (<code>faultdeck remote ping/inject/rollback</code>), <code>crates/report</code> (<code>Scenario</code>, <code>RunReport</code> JSON/HTML, SHA-256 hash, <code>compare_runs</code> history diff), and <code>crates/coordinator</code> (multi-target hub: registry/heartbeat/report archive). <code>crates/protocol</code> is an empty placeholder, not a workspace member. The MVP plan&#39;s toxiproxy adapter and scenario YAML DSL remain unimplemented; <code>todo.md</code> milestones FD-P1-4, FD-ARCH-1, FD-REPORT-1, FD-ARCH-2 are checked.</p><h2 id="findings-all-fixed-this-round-source-untouched" tabindex="-1">Findings (all fixed this round, source untouched) <a class="header-anchor" href="#findings-all-fixed-this-round-source-untouched" aria-label="Permalink to “Findings (all fixed this round, source untouched)”">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Page</th><th>Claim</th><th>Source evidence</th><th>Class</th><th>Severity</th><th>Fix</th></tr></thead><tbody><tr><td>F1</td><td>README.md Roadmap / README.zh.md 路线图</td><td>P0 status &quot;In development / 开发中&quot;</td><td>Zero implementation in the tree (no Cargo.toml/crates/examples/tests); plan milestones FD-P0-1..6 all unchecked (docs/design/mvp-plan.md:36-41)</td><td>Doc ahead of code</td><td>P0</td><td>Status → &quot;Not started / 未开始&quot;</td></tr><tr><td>F2</td><td>README.md / README.zh.md mode diagrams</td><td><code>![Mode A](/faultdeck/public/mode-a-agent-listen.svg)</code></td><td>Absolute <code>/faultdeck/public/...</code> paths 404 on the GitHub render (READMEs are not part of the vitepress site, so no base rewrite applies); files actually live at <code>docs/public/*.svg</code></td><td>Mismatch</td><td>P2</td><td>Rewritten to repo-relative <code>docs/public/mode-*.svg</code> (×3 per README)</td></tr><tr><td>F3</td><td>docs/zh/design/mvp-plan.md (site zh page)</td><td>zh page mirrors the en plan</td><td>en plan (docs/design/mvp-plan.md:47-57) carries three 2026-11-02 sections (cross-machine control / connection direction &amp; reports / coordinator); zh page ended at &quot;P1 预告&quot;</td><td>Mismatch</td><td>P1</td><td>Three sections translated faithfully and appended</td></tr><tr><td>F4</td><td>docs/design/mvp-plan.zh.md</td><td>Paired zh copy of the plan</td><td>Orphan: referenced by nothing (grep <code>mvp-plan.zh</code> = 0 hits), not in the vitepress site (sidebar uses <code>docs/zh/design/mvp-plan.md</code>), and stale — it contained the 2026-11-02 additions while the served zh page did not</td><td>Mismatch (stale duplicate)</td><td>P2</td><td>Deleted the orphan</td></tr></tbody></table><h2 id="verified-no-action" tabindex="-1">Verified, no action <a class="header-anchor" href="#verified-no-action" aria-label="Permalink to “Verified, no action”">​</a></h2><ul><li>README &quot;Repository Layout (target)&quot; is explicitly labeled as target — honest.</li><li>Status badge &quot;in development / 开发中&quot; describes the overall project (docs/design active); roadmap rows now carry per-phase truth.</li><li>mvp-plan acceptance gate &quot;100% of faults rolled back&quot; is a hard acceptance spec, not an achievement claim; <code>todo.md</code> &quot;SSH/管理 IP 永不被注入&quot; is a safety invariant — both legal per the copy standard.</li><li>AI-flavor sweep: no actionable hits (no bragging, no hollow-summary, no tutorial stance; emoji feature icons are vitepress theme config, not markdown decoration).</li><li>todo.md: 4 uniform unchecked requirement lines with acceptance criteria and prerequisites — already in ledger form, no changes.</li><li>README badges: license/Rust/backend/platform/status all point at real targets (<code>docs/design/mvp-plan.md</code>, LICENSE); zh badges point at the zh plan page.</li></ul><hr><h1 id="round-2026-11-05-—-full-re-audit-after-the-implementation-landed" tabindex="-1">Round 2026-11-05 — full re-audit after the implementation landed <a class="header-anchor" href="#round-2026-11-05-—-full-re-audit-after-the-implementation-landed" aria-label="Permalink to “Round 2026-11-05 — full re-audit after the implementation landed”">​</a></h1><p>Method: <code>~/workspaces/standards/文档与源码一致性审计规范.md</code> (three buckets, six steps). Doc surface re-enumerated: README.md, README.zh.md, docs/** (en+zh), design/mvp-plan, review archive, plus the public face (<code>gh repo view cuihairu/faultdeck</code>). Every claim re-evidenced at file:line against the current tree; negative conclusions verified the search path first (e.g. <code>grep -rn watchdog|lease crates/</code> = 0 hits across the actual crate tree).</p><h2 id="findings-all-fixed-this-round-source-untouched-1" tabindex="-1">Findings (all fixed this round, source untouched) <a class="header-anchor" href="#findings-all-fixed-this-round-source-untouched-1" aria-label="Permalink to “Findings (all fixed this round, source untouched)”">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Page</th><th>Claim</th><th>Source evidence</th><th>Class</th><th>Severity</th><th>Fix</th></tr></thead><tbody><tr><td>F5</td><td>docs/index.md:28 · docs/zh/index.md:28</td><td>&quot;Watchdog + lease + forced rollback — faults are undone even if the process is killed&quot; presented as a shipped feature</td><td>No watchdog/lease/forced-rollback code anywhere (<code>grep -rn &quot;watchdog|lease&quot; crates/</code> = 0 hits); exists only as the unchecked plan item FD-P0-4 (docs/design/mvp-plan.md:39)</td><td>Doc ahead of code</td><td>P0</td><td>Feature rewritten to real guarantees (idempotent rollback, foreign-qdisc refusal, leftover cleanup); kill-safe rollback marked planned</td></tr><tr><td>F6</td><td>README.md:14 · README.zh.md:15</td><td>&quot;Fault types: latency, packet loss, disconnect, blackhole, bandwidth throttle. Scenarios are prebuilt…&quot;</td><td><code>FaultSpec</code> has only Latency/Loss/Disconnect (crates/core/src/lib.rs:28); no blackhole/bandwidth/template code in the tree</td><td>Doc ahead of code</td><td>P1</td><td>Headline paragraph split into shipped (latency/loss/disconnect) vs planned (blackhole, bandwidth, P2 templates)</td></tr><tr><td>F7</td><td>docs/index.md:25 · docs/zh/index.md:25</td><td>&quot;Experiment YAML … Toxiproxy / tc netem / WinDivert decide implementation&quot; as current behavior</td><td>Backend today is tc netem (crates/netem) + iptables (crates/agent/src/firewall.rs); no YAML DSL, no toxiproxy crate, no WinDivert</td><td>Doc ahead of code</td><td>P1</td><td>Reworded to current validate-then-dispatch model; YAML DSL / Toxiproxy / WinDivert marked planned</td></tr><tr><td>F8</td><td>README.md Roadmap · README.zh.md 路线图</td><td>P0 status &quot;Not started / 未开始&quot;</td><td>CLI, latency/loss/disconnect injection, auto-recovery rollback and JSON report all live (crates/cli, crates/netem, crates/agent, crates/report)</td><td>Code ahead of doc</td><td>P1</td><td>Status → &quot;Partially shipped&quot; with explicit pending items</td></tr><tr><td>F9</td><td>README.md Roadmap · README.zh.md 路线图</td><td>P3 lists &quot;remote agent, CI integration&quot; as Planned</td><td>crates/agent + crates/coordinator shipped; CI build/test runs (.github/workflows/rust.yml)</td><td>Code ahead of doc</td><td>P2</td><td>Status → &quot;Partially shipped&quot; (agent/coordinator/CI live; WinDivert, Web UI pending)</td></tr><tr><td>F10</td><td>docs/quickstart.md:20 · docs/zh/quickstart.md:21</td><td>&quot;two binaries&quot;</td><td><code>cargo build</code> produces three: faultdeck, faultdeck-agent, faultdeck-coordinator (crates/coordinator/src/main.rs)</td><td>Code ahead of doc</td><td>P2</td><td>Coordinator row added to the binary table</td></tr><tr><td>F11</td><td>docs/remote-agents.md:24 · docs/zh/remote-agents.md:24</td><td>Only the no-management warning documented</td><td>warn_insecure_bind also warns on non-loopback bind without token (crates/agent/src/lib.rs:141-149, called from crates/agent/src/main.rs:58)</td><td>Code ahead of doc</td><td>P2</td><td>Both startup warnings documented</td></tr><tr><td>F12</td><td>docs/quickstart.md:72 · docs/zh/quickstart.md:72</td><td>&quot;One fault at a time per agent connection lifecycle&quot;</td><td>Applied state is shared across connections (<code>Arc&lt;Mutex&lt;HashSet&gt;&gt;</code> behind serve_on, crates/agent/src/lib.rs) — the wording froze the pre-fix per-connection behavior</td><td>Mismatch</td><td>P2</td><td>Reworded: state survives across connections, not across restarts</td></tr><tr><td>F13</td><td>docs/netem-faults.md:59 · docs/zh/netem-faults.md:59</td><td>Disconnect = &quot;one <code>-d ADDR/PREFIX -j DROP</code> rule per target network&quot;</td><td>Source networks match with <code>-s</code>; port-level disconnect installs <code>-p tcp</code> + <code>-p udp --dport</code> rules; partial install tears the chain down (crates/agent/src/firewall.rs:135-184)</td><td>Mismatch</td><td>P2</td><td>Disconnect section rewritten to current rule model</td></tr><tr><td>F14</td><td>docs/configuration.md:53 · docs/zh/configuration.md:51</td><td>&quot;There are no environment variables&quot;</td><td>FAULTDECK_TIMEOUT_SECS overrides the CLI&#39;s 5s read/write timeout (crates/cli/src/main.rs:104-110)</td><td>Mismatch</td><td>P2</td><td>Env var documented; closing line corrected</td></tr><tr><td>F15</td><td>README.md:67-74 · README.zh.md:68-75</td><td>&quot;Repository Layout (target)&quot; listing scenario/backend/toxiproxy/safety crates + examples/ + tests/</td><td>Tree actually has core/netem/agent/cli/report/coordinator (+ empty protocol/ placeholder); no examples/, no root tests/ — the old &quot;target&quot; no longer matches the trajectory</td><td>Mismatch</td><td>P2</td><td>Layout now shows the real tree; planned additions listed as prose</td></tr><tr><td>F16</td><td>README.md:31 · README.zh.md:31</td><td>Architecture diagram shows Toxiproxy/WinDivert adapters without status markers</td><td>Only tc/netem and iptables adapters implemented</td><td>Mismatch</td><td>P2</td><td>Diagram marks live vs planned backends</td></tr></tbody></table><h2 id="verified-no-action-1" tabindex="-1">Verified, no action <a class="header-anchor" href="#verified-no-action-1" aria-label="Permalink to “Verified, no action”">​</a></h2><ul><li>GitHub About line: &quot;latency/loss/disconnect/partition scenarios as reproducible automated tests&quot; — all four map to implemented faults (a CIDR partition is the iptables disconnect); homepageUrl points at the real site.</li><li>docs/design/mvp-plan.md marks unimplemented scope honestly (FD-P0-4 etc. unchecked); reports.md / remote-agents.md protocol sections re-verified against crates/report/src/lib.rs:79-88 and the WireMessage envelope (crates/coordinator/src/lib.rs) — accurate, including &quot;queued; live dispatch not wired yet&quot; (crates/coordinator/src/lib.rs:173).</li><li>configuration.md constants re-verified: MAX_INJECTION_BYTES 64 KiB, PILOT_QDISC_HANDLE 100:, netem handle 50:, MAX_LATENCY_MS 24h (crates/core/src/lib.rs:104), chain FAULTDECK in mangle (crates/agent/src/firewall.rs:9-10).</li><li>AI-flavor sweep per <code>~/workspaces/standards/文档写作风格规范.md</code>: banned vocabulary (标志着/赋能/打造/领先/自研/从零/综上所述/排比三连/seamless/robust/ leverage…) grep = 0 hits across README + docs; the fixes above removed the remaining over-claims and template-y emphasis lines. Vitepress feature icons remain theme config, not markdown decoration (carried over from the 2026-11-02 verdict).</li></ul>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};